import { promises as fs } from "fs";
import path from "path";
import { randomUUID } from "crypto";

const DATA_FILE = path.join(process.cwd(), "data", "books.json");

export async function readBooks() {
  try {
    const raw = await fs.readFile(DATA_FILE, "utf8");
    const books = JSON.parse(raw);
    return Array.isArray(books) ? books : [];
  } catch {
    return [];
  }
}

async function writeBooks(books) {
  await fs.mkdir(path.dirname(DATA_FILE), { recursive: true });
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2), "utf8");
}

export async function getBook(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes = "", status = "reading" }) {
  const books = await readBooks();
  const book = {
    id: randomUUID(),
    title,
    author,
    notes,
    status,
    createdAt: new Date().toISOString(),
    finishedAt: status === "finished" ? new Date().toISOString() : null,
  };
  books.push(book);
  await writeBooks(books);
  return book;
}

export async function updateBook(id, patch) {
  const books = await readBooks();
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;
  books[index] = { ...books[index], ...patch };
  await writeBooks(books);
  return books[index];
}

"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import { addBook, updateBook } from "./books.js";

export async function addBookAction(formData) {
  const title = String(formData.get("title") ?? "").trim();
  const author = String(formData.get("author") ?? "").trim();
  const notes = String(formData.get("notes") ?? "").trim();
  const status = formData.get("status") === "finished" ? "finished" : "reading";
  if (!title) return;

  const book = await addBook({ title, author, notes, status });
  redirect(`/books/${book.id}`);
}

export async function setStatusAction(formData) {
  const id = String(formData.get("id") ?? "");
  const status = formData.get("status") === "finished" ? "finished" : "reading";
  if (!id) return;

  await updateBook(id, {
    status,
    finishedAt: status === "finished" ? new Date().toISOString() : null,
  });
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
  redirect(`/books/${id}`);
}

export async function saveNotesAction(formData) {
  const id = String(formData.get("id") ?? "");
  const notes = String(formData.get("notes") ?? "");
  if (!id) return;

  await updateBook(id, { notes });
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
  redirect(`/books/${id}`);
}

import Link from "next/link";
import "./globals.css";

export const metadata = {
  title: "My Books",
  description: "A small book tracker",
};

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      <body>
        <header className="site-header">
          <Link href="/" className="site-title">
            My Books
          </Link>
        </header>
        <main className="container">{children}</main>
      </body>
    </html>
  );
}

