import Link from "next/link";
import { readBooks } from "../lib/books.js";

export const dynamic = "force-dynamic";

export default async function HomePage() {
  const books = await readBooks();
  const reading = books.filter((book) => book.status === "reading");
  const finished = books.filter((book) => book.status === "finished");

  return (
    <div>
      <div className="top-row">
        <h1 className="page-title">Reading list</h1>
        <Link href="/books/new" className="button">
          Add a book
        </Link>
      </div>

      <section className="section">
        <h2>Currently reading ({reading.length})</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing here yet.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <li key={book.id}>
                <Link href={`/books/${book.id}`} className="book-card">
                  <span className="book-title">{book.title}</span>
                  {book.author ? (
                    <span className="book-author"> — {book.author}</span>
                  ) : null}
                </Link>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="section">
        <h2>Finished ({finished.length})</h2>
        {finished.length === 0 ? (
          <p className="empty">Nothing here yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <li key={book.id}>
                <Link href={`/books/${book.id}`} className="book-card">
                  <span className="book-title">{book.title}</span>
                  {book.author ? (
                    <span className="book-author"> — {book.author}</span>
                  ) : null}
                </Link>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { getBook } from "../../../lib/books.js";
import { setStatusAction, saveNotesAction } from "../../../lib/actions.js";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  return { title: book ? `${book.title} — My Books` : "Book not found" };
}

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <div>
      <h1 className="page-title">
        {book.title}
        <span className={`badge ${book.status}`}>
          {book.status === "finished" ? "Finished" : "Reading"}
        </span>
      </h1>
      <p className="meta">{book.author || "Unknown author"}</p>

      <div className="card">
        <h2 style={{ margin: 0, fontSize: "1rem" }}>Notes</h2>
        {book.notes ? (
          <p className="notes">{book.notes}</p>
        ) : (
          <p className="empty">No notes yet.</p>
        )}
        <form action={saveNotesAction}>
          <input type="hidden" name="id" value={book.id} />
          <label htmlFor="notes">Edit notes</label>
          <textarea id="notes" name="notes" defaultValue={book.notes ?? ""} />
          <div>
            <button type="submit">Save notes</button>
          </div>
        </form>
      </div>

      <div className="actions">
        {book.status === "reading" ? (
          <form action={setStatusAction}>
            <input type="hidden" name="id" value={book.id} />
            <input type="hidden" name="status" value="finished" />
            <button type="submit">Mark as finished</button>
          </form>
        ) : (
          <form action={setStatusAction}>
            <input type="hidden" name="id" value={book.id} />
            <input type="hidden" name="status" value="reading" />
            <button type="submit">Move back to reading</button>
          </form>
        )}
      </div>

      <div className="card">
        <h2 style={{ margin: 0, fontSize: "1rem" }}>Share this book</h2>
        <p className="meta">Send this link to a friend:</p>
        <div className="link-box">/books/{book.id}</div>
      </div>

      <p>
        <Link href="/">Back to reading list</Link>
      </p>
    </div>
  );
}

